import React, { useState, useEffect } from 'react';
import './Following.css';

const Following = () => {
  const [isActive, setIsActive] = useState(false);
  const [location, setLocation] = useState('');
  const [status, setStatus] = useState('');
  const [alertSent, setAlertSent] = useState(false);

  useEffect(() => {
    if (isActive) {
      getCurrentLocation();
    }
  }, [isActive]);

  const getCurrentLocation = async () => {
    try {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            const { latitude, longitude } = position.coords;
            setLocation(`${latitude.toFixed(6)}, ${longitude.toFixed(6)}`);
          },
          () => setLocation('Location unavailable')
        );
      }
    } catch (error) {
      setLocation('Location error');
    }
  };

  const sendFollowingAlert = async () => {
    const contacts = JSON.parse(localStorage.getItem('safehaven_emergency_contacts') || '[]');
    const userName = localStorage.getItem('safehaven_user_name') || 'Someone';
    const userPhone = localStorage.getItem('safehaven_user_phone') || 'Unknown';

    const locationLink = location ? `https://www.google.com/maps?q=${location}` : '';
    const message = `🚨 FOLLOWING ALERT 🚨\n\n${userName} (${userPhone}) feels they are being followed!\n\nLocation: ${location}\n${locationLink ? `Map: ${locationLink}\n` : ''}\nPlease check on them immediately!`;

    contacts.forEach((contact, idx) => {
      const cleanNumber = contact.phone.replace(/[^\d]/g, '');
      const url = `https://wa.me/${cleanNumber}?text=${encodeURIComponent(message)}`;
      setTimeout(() => window.open(url, '_blank'), idx * 500);
    });

    setAlertSent(true);
    setStatus('Following alert sent to emergency contacts!');
  };

  const startFollowingMode = () => {
    setIsActive(true);
    setAlertSent(false);
    setStatus('Following mode activated - location tracking started');
  };

  const stopFollowingMode = () => {
    setIsActive(false);
    setAlertSent(false);
    setStatus('Following mode deactivated');
  };

  return (
    <div className="following-container">
      <h2>👁️ Being Followed Alert</h2>

      <div className="alert-description">
        <p>Use this if you feel someone is following you. It will send your location to emergency contacts.</p>
      </div>

      <div className="following-status">
        {!isActive ? (
          <button className="start-following-btn" onClick={startFollowingMode}>
            🚨 I'm Being Followed
          </button>
        ) : (
          <div className="active-following">
            <div className="location-info">
              <p><strong>Current Location:</strong></p>
              <p>{location || 'Getting location...'}</p>
            </div>

            <div className="action-buttons">
              <button className="send-alert-btn" onClick={sendFollowingAlert} disabled={alertSent}>
                {alertSent ? '✅ Alert Sent' : '📱 Send Alert Now'}
              </button>
              <button className="stop-btn" onClick={stopFollowingMode}>
                Stop Following Mode
              </button>
            </div>
          </div>
        )}
      </div>

      {status && <div className="status-message">{status}</div>}

      <div className="safety-tips">
        <h3>🛡️ Safety Tips:</h3>
        <ul>
          <li>Stay in well-lit, populated areas</li>
          <li>Don't go home if being followed</li>
          <li>Go to a police station or public place</li>
          <li>Call emergency services if in immediate danger</li>
          <li>Trust your instincts</li>
        </ul>
      </div>
    </div>
  );
};

export default Following;
